function haversineMeters(lat1, lon1, lat2, lon2) {
  const R = 6371000; // mean Earth radius in meters
  const rad = (d) => (d * Math.PI) / 180;
  const dPhi = rad(lat2 - lat1);
  const dLam = rad(lon2 - lon1);
  const a = Math.sin(dPhi / 2) ** 2 +
    Math.cos(rad(lat1)) * Math.cos(rad(lat2)) * Math.sin(dLam / 2) ** 2;
  return 2 * R * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
}

haversineMeters(48.861111, 2.336389, 48.86, 2.327); // 697.9 (Louvre to Orsay)
haversineMeters(0, 179.9, 0, -179.9);               // 22239 (across the antimeridian)

-- PostGIS: GiST index, then an index-aware radius filter (meters on geography)
CREATE INDEX sensors_loc_gix ON sensors USING GIST (location);

SELECT id, reading
FROM sensors
WHERE ST_DWithin(location,
                 ST_MakePoint(2.336389, 48.861111)::geography,
                 500);

